"""Step type definitions.

All step types inherit from :class:`BaseStep` which carries the shared
``model_config`` and ``id`` field. Each subclass adds a ``kind`` discriminator
literal plus its own fields.

The :data:`Step` union uses Pydantic's discriminated union mechanism.  Because
YAML authors do not write ``kind:`` explicitly, use :func:`parse_step` (which
calls :func:`infer_step_kind` to inject ``kind`` before model validation).

Step kinds and their discriminating YAML keys::

    instructions  → AutonomousStep
    collect       → CollectStep
    action        → ActionStep  (canonical)
    utter         → ActionStep  (legacy; value moved to action field by loader)
    noop: true    → RouteStep
    execute_tool  → ExecuteStep
    set_memory    → SetMemoryStep
    call          → CallStep
    link          → LinkStep
    id == "END"   → EndStep     (sentinel; no payload)

``next`` field semantics:
    All step types (except ``RouteStep`` and ``LinkStep``) accept ``next`` as
    either a plain step-id string *or* a list of conditional
    :class:`~rasa.mantle.skills.conditions.NextBranch` dicts.  Plain strings
    are stored as-is; branch lists are parsed via
    :func:`~rasa.mantle.skills.conditions.parse_next_branches` and stored as
    :class:`~rasa.mantle.skills.conditions.NextBranch` objects.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Annotated, Any, Literal, NoReturn, Union

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    field_validator,
    model_serializer,
    model_validator,
)
from pydantic import (
    ValidationError as PydanticValidationError,
)

from rasa.exceptions import ValidationError
from rasa.mantle.skills.conditions import Condition, NextBranch, parse_next_branches
from rasa.shared.core.constants import ACTION_LISTEN_NAME
from rasa.shared.core.flows.steps.constants import END_STEP

# Ends the conversation from an ordered block. Named for the skill model rather
# than reusing the CALM ``action_hangup``: this engine has skills and tools, not
# actions, and the name matches the ``hangup`` framework tool builders already
# know. (``action_listen`` is renamed separately in ENG-3067.)
BUILTIN_HANGUP = "hangup"

# Built-in actions an :class:`ActionStep` may reference besides ``utter_*``
# responses. This is the executor's actual dispatch surface — the project
# validator checks against the same set so a flow can never pass validation
# with an action the step executor cannot run.
SUPPORTED_BUILTIN_ACTIONS = frozenset({BUILTIN_HANGUP, ACTION_LISTEN_NAME})

# ---------------------------------------------------------------------------
# Base
# ---------------------------------------------------------------------------


class BaseStep(BaseModel):
    """Shared configuration and id field for all step types."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    id: str


# ---------------------------------------------------------------------------
# Concrete step types
# ---------------------------------------------------------------------------


# ``next`` can be a plain step-id or a list of conditional branches.
Next = str | list[NextBranch] | None


class DTMFConfig(BaseModel):
    """Configure keypad input for a collect step."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    length: int | None = None
    finish_on_key: str | None = None
    allow_audio_input: bool = True

    @model_validator(mode="before")
    @classmethod
    def _reject_multiple_completion_rules(cls, value: Any) -> Any:
        if (
            isinstance(value, Mapping)
            and "length" in value
            and "finish_on_key" in value
        ):
            raise ValueError(
                "DTMF configuration cannot have both 'length' and 'finish_on_key'."
            )
        return value

    @model_validator(mode="after")
    def _require_completion_rule(self) -> DTMFConfig:
        """Require one keypad completion rule.

        The handler finishes input only when ``length`` is reached or
        ``finish_on_key`` is pressed. With neither set, keypresses are buffered
        and then discarded.
        """
        if self.length is None and self.finish_on_key is None:
            raise ValueError(
                "DTMF configuration must set either 'length' or 'finish_on_key'."
            )
        return self

    @model_serializer
    def _serialize(self) -> dict[str, Any]:
        """Omit unset completion keys so a dump can be parsed again.

        The before-validator treats the presence of both ``length`` and
        ``finish_on_key`` as two completion rules, including when one value is
        ``None``. A default dump would emit those keys and fail on the way back
        in.
        """
        data: dict[str, Any] = {"allow_audio_input": self.allow_audio_input}
        if self.length is not None:
            data["length"] = self.length
        if self.finish_on_key is not None:
            data["finish_on_key"] = self.finish_on_key
        return data


class AutonomousStep(BaseStep):
    """An LLM-driven step with free-form instructions."""

    kind: Literal["autonomous"] = "autonomous"
    instructions: str
    complete_when: Condition | None = None
    optional: bool = False
    next: Next = None

    @field_validator("complete_when", mode="before")
    @classmethod
    def _expression_only_complete_when(cls, value: Any) -> Any:
        """Step-level ``complete_when`` must be a plain expression string."""
        if value is None or isinstance(value, str):
            return value
        raise ValueError(
            "step complete_when must be an expression string "
            "(criteria / mappings are only allowed on skill frontmatter)"
        )


class CollectStep(BaseStep):
    """A guided data-collection step that fills a single memory entry.

    The LLM records the value via ``set_fields``; an optional
    ``run_after_setting_<collect>`` memory validation tool validates and
    derives side effects.
    """

    kind: Literal["collect"] = "collect"
    collect: str
    utterance: str | None = None
    description: str | None = None
    dtmf: DTMFConfig | None = None
    # When True the collect step is never skipped for an already-filled value —
    # the question is always asked when the step is reached (e.g. confirm-then-
    # act). Early ``set_fields`` writes are still allowed while the entry is
    # empty. Default False keeps the field settable ahead of time and skips the
    # step when already filled.
    ask_before_filling: bool = False
    next: Next = None


class ActionStep(BaseStep):
    """Execute a response utterance or a custom action server call.

    ``action: "utter_*"``  → bot utters the named response template.
    ``action: "action_*"`` → calls the custom action server.

    The loader also accepts legacy ``utter:`` keys and normalises them to
    ``action:``.
    """

    kind: Literal["action"] = "action"
    action: str
    next: Next = None


class RouteStep(BaseStep):
    """Evaluate a list of conditional branches and redirect to the first match.

    ``next`` may be a list of :class:`NextBranch` dicts (conditional routing)
    or a plain step-id string (unconditional pass-through noop).
    """

    kind: Literal["route"] = "route"
    noop: bool = True
    next: str | list[NextBranch] = Field(default_factory=list)


class ExecuteStep(BaseStep):
    """Invoke a named tool with optional parameters."""

    kind: Literal["execute"] = "execute"
    execute_tool: str
    parameters: dict[str, Any] = Field(default_factory=dict)
    next: Next = None


class SetMemoryStep(BaseStep):
    """Set one or more memory keys to literal values."""

    kind: Literal["set_memory"] = "set_memory"
    set_memory: dict[str, Any]
    next: Next = None


class CallStep(BaseStep):
    """Push a new flow frame and return when the callee completes."""

    kind: Literal["call"] = "call"
    call: str
    next: Next = None


class LinkStep(BaseStep):
    """Replace the current flow frame with another flow (no return)."""

    kind: Literal["link"] = "link"
    link: str


class EndStep(BaseStep):
    """Sentinel step that marks the end of a flow."""

    kind: Literal["end"] = "end"
    id: str = END_STEP


# ---------------------------------------------------------------------------
# Discriminated union
# ---------------------------------------------------------------------------

Step = Annotated[
    Union[
        AutonomousStep,
        CollectStep,
        ActionStep,
        RouteStep,
        ExecuteStep,
        SetMemoryStep,
        CallStep,
        LinkStep,
        EndStep,
    ],
    Field(discriminator="kind"),
]


# ---------------------------------------------------------------------------
# Loader helpers
# ---------------------------------------------------------------------------

_KIND_BY_KEY = {
    "instructions": "autonomous",
    "collect": "collect",
    "action": "action",
    "execute_tool": "execute",
    "set_memory": "set_memory",
    "call": "call",
    "link": "link",
}


def infer_step_kind(raw: dict[str, Any]) -> str:
    """Infer the ``kind`` discriminator from raw YAML keys.

    Keys are checked in priority order.  ``utter`` is normalised to ``action``
    (the value is moved to the ``action`` field by :func:`parse_step`).
    A step whose ``id`` is ``END_STEP`` (``"END"``) always resolves to ``end``.

    Raises:
        ValueError: If the kind cannot be determined from the available keys.
    """
    if raw.get("id") == END_STEP:
        return "end"

    # noop: true → route
    if raw.get("noop") is True:
        return "route"

    # legacy utter: alias
    if "utter" in raw:
        return "action"

    for key, kind in _KIND_BY_KEY.items():
        if key in raw:
            return kind

    raise ValueError(
        f"Cannot infer step kind from YAML keys {list(raw.keys())!r}. "
        "Expected one of: instructions, collect, action, utter, noop, "
        "execute_tool, set_memory, call, link; or id == 'END'."
    )


# Collect-only keys removed from the schema; each entry is
# (yaml_key, error_code, message_template with {step_id}).
_COLLECT_OUTDATED_STEP_KEYS: tuple[tuple[str, str, str], ...] = (
    (
        "force_collection",
        "skill.step.outdated_force_collection",
        "Unknown step property 'force_collection' on step '{step_id}'. "
        "Use 'ask_before_filling: true' instead.",
    ),
    (
        "tool",
        "skill.step.outdated_collect_tool",
        "Unknown property 'tool' on collect step '{step_id}'. "
        "Collect steps no longer take a 'tool:' override; values are "
        "recorded via 'set_fields', with an optional "
        "'run_after_setting_<field>' memory validation tool, or use an "
        "'execute_tool' step. Remove 'tool:' from this step.",
    ),
)


def _reject_outdated_step_properties(raw: dict[str, Any], kind: str) -> None:
    """Raise when YAML uses removed step keys with an actionable migration hint.

    Generic unknown keys are rejected by ``extra="forbid"`` on :class:`BaseStep`.
    Known renames/removals get explicit messages here so authors are not left
    with a bare pydantic "extra inputs are not permitted" error.
    """
    if kind != "collect":
        return

    step_id = raw.get("id", "<unknown>")
    for key, code, message_template in _COLLECT_OUTDATED_STEP_KEYS:
        if key in raw:
            raise ValidationError(
                code=code,
                event_info=message_template.format(step_id=step_id),
            )


def _format_step_validation_issue(issue: dict[str, Any], *, step_id: str) -> str:
    """Turn one pydantic issue into an author-facing step error line."""
    loc = issue.get("loc", ())
    field = ".".join(str(part) for part in loc if str(part) != "kind")
    issue_type = issue.get("type")

    if issue_type == "extra_forbidden" and len(loc) == 1:
        key = str(loc[0])
        return (
            f"Unknown step property {key!r} on step {step_id!r}. "
            "Remove it or check for typos."
        )
    if issue_type == "missing" and field:
        return f"Step {step_id!r} is missing required property {field!r}."
    if field:
        return (
            f"Step {step_id!r}, property {field!r}: "
            f"{issue.get('msg', 'invalid value')}."
        )
    return f"Step {step_id!r}: {issue.get('msg', 'invalid value')}."


def _raise_on_step_validation_error(
    error: PydanticValidationError,
    *,
    step_id: str,
) -> NoReturn:
    """Normalize pydantic step validation failures to :class:`ValidationError`."""
    messages = [
        _format_step_validation_issue(issue, step_id=step_id)
        for issue in error.errors()
    ]
    raise ValidationError(
        code="skill.step.invalid",
        event_info=" ".join(messages),
    ) from error


def parse_step(raw: dict[str, Any]) -> Step:
    """Parse a raw YAML step dict into the appropriate :data:`Step` subtype.

    Handles:
    - ``kind`` injection via :func:`infer_step_kind`
    - ``utter:`` → ``action:`` normalisation
    - ``next:`` list of branch dicts → :class:`NextBranch` list (for RouteStep)
    - rejection of unknown and removed step properties
    """
    raw = dict(raw)  # shallow copy — we'll mutate before validation

    kind = infer_step_kind(raw)
    raw["kind"] = kind

    # Normalise legacy utter: key
    if "utter" in raw and "action" not in raw:
        raw["action"] = raw.pop("utter")

    _reject_outdated_step_properties(raw, kind)

    # Normalise conditional next: list of branch dicts → NextBranch objects.
    # Applies to all step kinds that carry a Next field (route + action/collect/etc.).
    if isinstance(raw.get("next"), list):
        raw["next"] = [
            b.model_dump(by_alias=True) for b in parse_next_branches(raw["next"])
        ]

    # EndStep has no extra fields beyond id
    if kind == "end":
        return EndStep()

    # Use TypeAdapter-style dispatch via the discriminated union
    # We validate via the specific class directly to get clear error messages.
    _cls_map: dict[str, type[BaseModel]] = {
        "autonomous": AutonomousStep,
        "collect": CollectStep,
        "action": ActionStep,
        "route": RouteStep,
        "execute": ExecuteStep,
        "set_memory": SetMemoryStep,
        "call": CallStep,
        "link": LinkStep,
        "end": EndStep,
    }
    cls = _cls_map[kind]
    step_id = str(raw.get("id", "<unknown>"))
    try:
        return cls.model_validate(raw)  # type: ignore[return-value]
    except PydanticValidationError as error:
        _raise_on_step_validation_error(error, step_id=step_id)
